#!/usr/bin/env bash
# pod_validate.sh -- self-contained GPU validation for the Pomerance CUDA engine.
#
# Drop this single file on any fresh RunPod pod with an NVIDIA GPU and a CUDA
# toolkit, then run it. No repo access, no tokens, no file transfer: the
# sources are embedded at the bottom of this script.
#
#   bash pod_validate.sh              # build + on-device selftest + A/B
#   bash pod_validate.sh --search     # ...then start the production search
#
# It answers one question: does this engine work correctly on real hardware,
# and how much faster is it than the record kernel?
set -uo pipefail

WORK="${WORK:-$HOME/pomerance-cuda}"
mkdir -p "$WORK" && cd "$WORK"

echo "== unpacking embedded sources =="
sed -n '/^__PAYLOAD__$/,$p' "$0" | tail -n +2 | base64 -d | tar xzf - || exit 1
ls

echo
echo "== environment =="
nvidia-smi --query-gpu=index,name,compute_cap,memory.total,driver_version \
           --format=csv,noheader || { echo "no GPU visible"; exit 1; }
nvcc --version | tail -2 || { echo "nvcc not found - use a CUDA devel image"; exit 1; }
CC_RAW=$(nvidia-smi --query-gpu=compute_cap --format=csv,noheader | head -1 | tr -d '. ')
ARCH="${ARCH:-sm_${CC_RAW:-89}}"
echo "building for $ARCH"

echo
echo "== 1/4  host-side proof of the exact device math =="
make -s host_test && ./host_test || { echo "HOST MATH FAILED"; exit 1; }

echo
echo "== 2/4  build CUDA engine =="
make -s search_cuda ARCH="$ARCH" || { echo "BUILD FAILED"; exit 1; }

P=1000000000000000000000000103          # 10^27 + 103, the open target

echo
echo "== 3/4  on-device selftest =="
echo "   (transport identity, exact order 32, cover points on E0 - on the GPU)"
POM_SELFTEST=only ./search_cuda "$P" 1 1000 x16halvenonsplit || {
  echo "DEVICE SELFTEST FAILED"; exit 3; }

echo
echo "== 4/4  same-seed A/B on the frontier prime =="
AB=${AB:-1500000000}                    # legacy marks; cover gets AB/4 curves
COV=$((AB / 4))
echo "-- legacy record kernel: $AB marks --"
t0=$(date +%s.%N)
POM_SOURCE=legacy POM_SELFTEST=0 ./search_cuda "$P" 7 "$AB" x16halvenonsplit 2000000000 2>&1 | tail -2
t1=$(date +%s.%N)
echo "-- cover kernel: $COV cover curves (identical hazard) --"
POM_SELFTEST=0 ./search_cuda "$P" 7 "$COV" x16halvenonsplit 2000000000 2>&1 | tail -2
t2=$(date +%s.%N)

awk -v a="$t0" -v b="$t1" -v c="$t2" -v cov="$COV" 'BEGIN{
  L=b-a; C=c-b;
  rate = C>0 ? cov/C : 0;
  printf "\n==================================================\n";
  printf " legacy record kernel : %8.1f s\n", L;
  printf " cover kernel         : %8.1f s   (equal hazard)\n", C;
  printf " MEASURED SPEEDUP     : %8.2fx\n", L/C;
  printf " cover rate           : %8.2f M cover-curves/s\n", rate/1e6;
  if (rate > 0) {
    lo = 5.53e11/rate/3600.0; hi = 7.91e11/rate/3600.0;
    printf "\n expected time to a triple on THIS GPU: %.1f - %.1f h\n", lo, hi;
    printf "   median  (0.69x mean): %.1f - %.1f h\n", 0.693*lo, 0.693*hi;
    printf "   95th pct (3x mean)  : %.1f - %.1f h\n", 3*lo, 3*hi;
  }
  printf "==================================================\n";
}'

if [ "${1:-}" = "--search" ]; then
  echo; echo "== production search on $P =="
  ./search_cuda "$P" 1 800000000000 x16halvenonsplit 2000000000
fi

echo; echo "VALIDATION COMPLETE"
exit 0

__PAYLOAD__

